// Benchmark stats loader.
//
// Source: `stats.json` lives in the gtm.rs repo at the repository root, next
// to the committed BENCHMARK.md. It is regenerated by `scripts/bench/render.sh`
// after every automated benchmark run (a "living document" — copy the freshly
// generated file over `./benchmark-stats.json` to refresh this page). The
// harness measures gtm headlessly; cliamp reference runs appear in `runs` with
// `cliamp/<fixture>` keys whenever the runner is invoked with CLIAMP_BIN set.
import raw from './benchmark-stats.json';

export interface BenchSeriesPoint {
  tag: string;
  date: string;
  value: number;
}

export interface BenchRun {
  file_sha256: string;
  peak_rss_kb: number;
  mean_rss_kb: number;
  rss_5s_kb: number;
  cpu_ms: number;
  t_ready_ms: number;
  rss_p50_kb: number;
  rss_p95_kb: number;
}

export interface BenchDelta {
  fixture: string;
  player: string;
  metric: string;
  label: string;
  previous: number;
  current: number;
  delta: number;
  delta_pct: number | null;
  regression: boolean;
}

export interface BenchmarkStats {
  schema: number;
  generated_at: string;
  run: { tag: string; date: string; commit: string; seconds: string };
  previous?: { tag: string; date: string; commit: string };
  series: Record<string, BenchSeriesPoint[]>;
  deltas: BenchDelta[];
  runs: Record<string, BenchRun>;
}

export const BENCHMARK_STATS = raw as unknown as BenchmarkStats;

/** `0.2.83+4b2e7a0+nightly` → `4b2e7a0` */
export function shortTag(tag: string): string {
  const m = /\+([a-f0-9]{7,})/.exec(tag);
  return m ? m[1] : tag.replace(/^0\.2\.83\+/, '');
}

export function formatKb(kb: number): string {
  return `${(kb / 1000).toFixed(2)} MB`;
}

export function formatMs(ms: number): string {
  return `${ms} ms`;
}

export function formatDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString('en', { month: 'short', day: 'numeric', year: 'numeric' });
}

export function formatDateTime(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('en', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}